import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - nextGeneration", () => {
  it.todo("returns an empty grid for an empty grid — [] → []");
  it.todo("lets a single cell die — [(0,0)] → []");
  it.todo(
    "Rule 1 Underpopulation: two adjacent cells with 1 neighbor each die — [(0,1),(1,1)] → []",
  );
  it.todo(
    "Rule 2 Survival: a live cell with 3 live neighbors lives on — [(0,0),(1,0),(2,0),(1,1)] keeps (1,0) alive",
  );
  it.todo(
    "Rule 3 Overpopulation: a live cell with more than 3 live neighbors dies — 3x3 ring plus center kills (1,1)",
  );
  it.todo(
    "Rule 4 Reproduction: a dead cell with exactly 3 live neighbors becomes alive — [(0,0),(1,0),(0,1)] → includes (1,1)",
  );
  it.todo(
    "Block still life stays unchanged — [(0,0),(1,0),(0,1),(1,1)] → same 4 cells",
  );
  it.todo(
    "Blinker oscillates: vertical becomes horizontal — [(0,0),(0,1),(0,2)] → [(-1,1),(0,1),(1,1)]",
  );
  it.todo(
    "Blinker oscillates back: horizontal becomes vertical — [(-1,1),(0,1),(1,1)] → [(0,0),(0,1),(0,2)]",
  );
  it.todo(
    "handles negative coordinates on the infinite grid — blinker at [(-5,-5),(-5,-4),(-5,-3)] → [(-6,-4),(-5,-4),(-4,-4)]",
  );
});

