const MAX_NEIGHBOURS_TO_SURVIVE = 3;

const survives = (cell: Cell, living: Cell[]): boolean => {
  const neighbours = liveNeighbourCount(cell, living);
  return (
    neighbours >= MIN_NEIGHBOURS_TO_SURVIVE &&
